insert into public.destinations
  (id, name, region, summary_en, summary_fil, latitude, longitude, elevation_m,
   pack_version, map_path, map_bytes, is_placeholder, updated_at)
values
  ('pulag', 'Mt. Pulag', 'Kabayan and Bokod, Benguet',
   'The highest mountain in Luzon, about 2,922 m, in the Mt. Pulag Protected Landscape. The Ambangeg Trail climbs about 7.4 km from the ranger station in Bashoy, Kabayan, through mossy forest and grassland to the summit. Book ahead, attend the DENR orientation in Ambangeg, Bokod, and hire a guide. It''s cold all year, with frost in the cool months, and high enough for altitude sickness.',
   'Ang pinakamataas na bundok sa Luzon, mga 2,922 m, sa Mt. Pulag Protected Landscape. Umaakyat ang Ambangeg Trail nang mga 7.4 km mula sa ranger station sa Bashoy, Kabayan, sa mossy forest at grassland hanggang summit. Mag-book nang maaga, dumalo sa DENR orientation sa Ambangeg, Bokod, at kumuha ng guide. Malamig buong taon, may frost sa malalamig na buwan, at sapat ang taas para sa altitude sickness.',
   16.5977263, 120.8987919, 2922,
   1, 'pulag-v1.pmtiles', 1469577, false, now())
on conflict (id) do update set
  name = excluded.name, region = excluded.region,
  summary_en = excluded.summary_en, summary_fil = excluded.summary_fil,
