insert into public.waypoints
  (id, trail_id, type, name, name_fil, note, latitude, longitude, elevation_m, position, distance_m)
values
  ('pulag-ambangeg-trail-jump-off', 'pulag-ambangeg-trail', 'jump_off', 'Babadak Ranger Station', 'Babadak Ranger Station',
   'The Ambangeg Trail''s ranger station in Bashoy, Kabayan (also spelled Badabak or Babalak). Register and attend the orientation at the DENR Visitor Center in Ambangeg, Bokod, first. Guides are hired here.',
   16.5721757, 120.8803508, null, 1, 0),
  ('pulag-ambangeg-trail-campsite-2', 'pulag-ambangeg-trail', 'campsite', 'Camp 1', 'Camp 1',
   'In the mossy forest, about 1 hour from the ranger station. Toilets nearby. The park office closed Camps 1 and 2 for clean-up in February 2025. Hikers reported camping here again in late 2025, and a 2026 guide says weekdays only. Ask the park office when you book. No open fires.',
   16.5795584, 120.8930636, 2577, 2, 2254),
  ('pulag-ambangeg-trail-water-3', 'pulag-ambangeg-trail', 'water', 'Spring between Camp 1 and Camp 2', 'Bukal sa pagitan ng Camp 1 at Camp 2',
   'Spring mapped in OpenStreetMap; flow isn''t confirmed. Treat all water before drinking.',
   16.5770887, 120.8975204, 2650, 3, 3058),
  ('pulag-ambangeg-trail-water-4', 'pulag-ambangeg-trail', 'water', 'Spring by Camp 2', 'Bukal sa tabi ng Camp 2',
   'Spring mapped in OpenStreetMap; flow isn''t confirmed. Treat all water before drinking. There''s no water past Camp 2.',
   16.584059, 120.9072982, 2700, 4, 4848),
  ('pulag-ambangeg-trail-campsite-5', 'pulag-ambangeg-trail', 'campsite', 'Camp 2', 'Camp 2',
   'At the edge of the grassland, about 2,700 m up. Altitude can affect people who sleep here. The park office closed Camps 1 and 2 for clean-up in February 2025. Hikers reported camping here again in late 2025, and a 2026 guide says weekdays only. Ask the park office when you book. No open fires.',
   16.5839276, 120.906581, 2709, 5, 4903),
  ('pulag-ambangeg-trail-summit', 'pulag-ambangeg-trail', 'summit', 'Mt. Pulag summit', 'Tuktok ng Mt. Pulag',
   'About 2,922 m (DENR-CAR); OpenStreetMap gives 2,928 m. Cold and windy, especially before sunrise, with frost in the cool months. No camping on the summit.',
   16.5977263, 120.8987919, 2928, 6, 7425);

insert into public.reference_passages
  (id, destination_id, topic, language, text, source, sources, as_of)
values
  ('pulag-01-about-mt-pulag-en', 'pulag', 'getting_there', 'en',
   'Mt. Pulag is the highest mountain in Luzon. It is protected by law as the Mt. Pulag Protected Landscape (RA 11685, 2022), which spans parts of Benguet, Ifugao and Nueva Vizcaya. DENR-CAR, which manages it, gives the summit as 2,922 m; Wikipedia and OpenStreetMap give up to 2,928 m. A park board chaired by DENR-CAR sets the rules and fees, and the park office is in Ambangeg, Bokod. The main Trails are Ambangeg (the easiest), Akiki, Tawangan and Ambaguio. Local communities hold the mountain sacred.',
   'lawphil.net, en.wikipedia.org, openstreetmap.org, car.denr.gov.ph, tourism.benguet.gov.ph',
   '[{"id": "P1", "title": "Republic Act No. 11685, Mt. Pulag Protected Landscape Act (2022)", "publisher": "Republic of the Philippines (text via LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2022/ra_11685_2022.html", "published": "2022-04-08", "accessed": "2026-10-10"}, {"id": "P2", "title": "Mount Pulag", "publisher": "Wikipedia contributors", "url": "https://en.wikipedia.org/wiki/Mount_Pulag", "published": "2026-08-15", "accessed": "2026-10-10"}, {"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P15", "title": "Moreno personally leads ground assessment in Mt. Pulag", "publisher": "DENR-CAR", "url": "https://car.denr.gov.ph/news-events/moreno-personally-leads-ground-assessment-in-mt-pulag/", "published": "2025", "accessed": "2026-10-10"}, {"id": "P17", "title": "DENR-CAR, DepEd-CAR forge landmark deal over Ambangeg site", "publisher": "DENR-CAR", "url": "https://car.denr.gov.ph/news-events/denr-car-deped-car-forge-landmark-deal-to-strengthen-unity-and-shared-land-use-over-ambangeg-site/", "published": "2025-05", "accessed": "2026-10-10"}, {"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}]'::jsonb, '2025-05'),
  ('pulag-01-about-mt-pulag-fil', 'pulag', 'getting_there', 'fil',
   'Ang Mt. Pulag ang pinakamataas na bundok sa Luzon. Protektado ito ng batas bilang Mt. Pulag Protected Landscape (RA 11685, 2022), na sakop ang bahagi ng Benguet, Ifugao at Nueva Vizcaya. Ayon sa DENR-CAR, na namamahala rito, 2,922 m ang summit; hanggang 2,928 m naman ayon sa Wikipedia at OpenStreetMap. Isang park board na pinamumunuan ng DENR-CAR ang nagtatakda ng rules at fees, at nasa Ambangeg, Bokod ang park office. Ang mga pangunahing Trail ay Ambangeg (pinakamadali), Akiki, Tawangan at Ambaguio. Sagrado ang bundok sa mga lokal na komunidad.',
   'lawphil.net, en.wikipedia.org, openstreetmap.org, car.denr.gov.ph, tourism.benguet.gov.ph',
   '[{"id": "P1", "title": "Republic Act No. 11685, Mt. Pulag Protected Landscape Act (2022)", "publisher": "Republic of the Philippines (text via LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2022/ra_11685_2022.html", "published": "2022-04-08", "accessed": "2026-10-10"}, {"id": "P2", "title": "Mount Pulag", "publisher": "Wikipedia contributors", "url": "https://en.wikipedia.org/wiki/Mount_Pulag", "published": "2026-08-15", "accessed": "2026-10-10"}, {"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P15", "title": "Moreno personally leads ground assessment in Mt. Pulag", "publisher": "DENR-CAR", "url": "https://car.denr.gov.ph/news-events/moreno-personally-leads-ground-assessment-in-mt-pulag/", "published": "2025", "accessed": "2026-10-10"}, {"id": "P17", "title": "DENR-CAR, DepEd-CAR forge landmark deal over Ambangeg site", "publisher": "DENR-CAR", "url": "https://car.denr.gov.ph/news-events/denr-car-deped-car-forge-landmark-deal-to-strengthen-unity-and-shared-land-use-over-ambangeg-site/", "published": "2025-05", "accessed": "2026-10-10"}, {"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}]'::jsonb, '2025-05'),
  ('pulag-02-booking-and-medical-certificate-en', 'pulag', 'registration', 'en',
   'You must book a Mt. Pulag climb with the park office in advance. In 2016 DENR turned back trekkers without a reservation (Rappler), and a 2026 guide (LakbayPinas) says walk-ins are still refused. A "fit to climb" medical certificate is required. Trip reports from November 2025 and February 2026 got one on the way for about ₱150; the 2026 guide names a clinic near the DENR Visitor Center. In 2015 the park head said people with heart problems, high blood pressure or asthma should not climb.',
   'rappler.com, lakbaypinas.com, philstar.com, ditokayshellan.com',
   '[{"id": "P27", "title": "DENR imposes stricter rules for Mt Pulag trekkers", "publisher": "Rappler", "url": "https://www.rappler.com/philippines/122314-denr-imposes-stricter-rules-for-mt-pulag-trekkers/", "published": "2016-02-13", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P29", "title": "Mt. Pulag freezes below zero", "publisher": "The Philippine Star", "url": "https://www.philstar.com/headlines/2015/12/29/1537575/mt-pulag-freezes-below-zero", "published": "2015-12-29", "accessed": "2026-10-10"}, {"id": "P28", "title": "Mt. Pulag Overnight Itinerary: Mighty and Spectacular Sea of Clouds (trip report, climbed about November 2025)", "publisher": "Dito Kay Shellan", "url": "https://ditokayshellan.com/2025/11/11/mt-pulag-overnight-itinerary-mighty-and-spectacular-sea-of-clouds/", "published": "2025-11-11", "accessed": "2026-10-10"}]'::jsonb, '2026-02'),
  ('pulag-02-booking-and-medical-certificate-fil', 'pulag', 'registration', 'fil',
   'Kailangang mag-book nang maaga sa park office bago umakyat sa Mt. Pulag. Noong 2016, pinabalik ng DENR ang mga walang reservation (Rappler), at ayon sa isang 2026 guide (LakbayPinas), hindi pa rin tinatanggap ang walk-in. Required ang "fit to climb" na medical certificate. Sa mga trip report noong Nobyembre 2025 at Pebrero 2026, kumuha sila nito sa daan sa mga ₱150; may clinic daw malapit sa DENR Visitor Center. Noong 2015, sinabi ng park head na hindi dapat umakyat ang may sakit sa puso, high blood o hika.',
   'rappler.com, lakbaypinas.com, philstar.com, ditokayshellan.com',
   '[{"id": "P27", "title": "DENR imposes stricter rules for Mt Pulag trekkers", "publisher": "Rappler", "url": "https://www.rappler.com/philippines/122314-denr-imposes-stricter-rules-for-mt-pulag-trekkers/", "published": "2016-02-13", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P29", "title": "Mt. Pulag freezes below zero", "publisher": "The Philippine Star", "url": "https://www.philstar.com/headlines/2015/12/29/1537575/mt-pulag-freezes-below-zero", "published": "2015-12-29", "accessed": "2026-10-10"}, {"id": "P28", "title": "Mt. Pulag Overnight Itinerary: Mighty and Spectacular Sea of Clouds (trip report, climbed about November 2025)", "publisher": "Dito Kay Shellan", "url": "https://ditokayshellan.com/2025/11/11/mt-pulag-overnight-itinerary-mighty-and-spectacular-sea-of-clouds/", "published": "2025-11-11", "accessed": "2026-10-10"}]'::jsonb, '2026-02'),
  ('pulag-03-fees-en', 'pulag', 'registration', 'en',
   'Benguet Province''s tourism page, updated in September 2026, lists these per-person fees for Mt. Pulag: the DENR entrance fee of ₱250 on weekdays and ₱350 on weekends and holidays ($15 for foreign guests), a Bokod environmental fee of ₱100, a Kabayan environmental and heritage fee of ₱300, and a ₱60 barangay fee for the Ambangeg (Babalak) Trail. Guides are paid separately. A 2026 travel guide reports the same DENR fee. Bring cash, and confirm the amounts with the park office when you book.',
   'tourism.benguet.gov.ph, lakbaypinas.com',
   '[{"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}]'::jsonb, '2026-09'),
  ('pulag-03-fees-fil', 'pulag', 'registration', 'fil',
   'Ayon sa tourism page ng Benguet Province, na-update noong Setyembre 2026, ito ang bayad bawat tao sa Mt. Pulag: DENR entrance fee na ₱250 tuwing weekday at ₱350 tuwing weekend at holiday ($15 sa foreign guests), environmental fee ng Bokod na ₱100, environmental at heritage fee ng Kabayan na ₱300, at ₱60 na barangay fee para sa Ambangeg (Babalak) Trail. Hiwalay ang bayad sa guide. Pareho ang DENR fee sa isang 2026 travel guide. Magdala ng cash, at i-confirm ang halaga sa park office kapag nag-book.',
   'tourism.benguet.gov.ph, lakbaypinas.com',
   '[{"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}]'::jsonb, '2026-09'),
  ('pulag-04-guides-and-porters-en', 'pulag', 'registration', 'en',
   'A local guide is required on every Mt. Pulag Trail. For the Ambangeg Trail, you hire one at the ranger station after the orientation. Benguet Province''s tourism page (2026) lists the guide association''s rate for the Babalak (Ambangeg) Trail as ₱1,500 for 1 to 5 hikers plus ₱300 per extra person, and porters at ₱1,200 for 12 kg plus ₱100 per extra kilo. A 2026 travel guide reported paying ₱1,200 per group of up to five. Confirm the rates at the ranger station.',
   'tourism.benguet.gov.ph, lakbaypinas.com',
   '[{"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}]'::jsonb, '2026-09'),
  ('pulag-04-guides-and-porters-fil', 'pulag', 'registration', 'fil',
   'Kailangan ng local guide sa lahat ng Trail ng Mt. Pulag. Sa Ambangeg Trail, sa ranger station kumukuha ng guide pagkatapos ng orientation. Ayon sa tourism page ng Benguet Province (2026), ₱1,500 ang guide sa Babalak (Ambangeg) Trail para sa 1 hanggang 5 hiker, dagdag na ₱300 bawat sobrang tao, at ₱1,200 ang porter para sa 12 kg, dagdag na ₱100 bawat sobrang kilo. Ayon sa isang 2026 travel guide, ₱1,200 ang ibinayad nila bawat grupo na hanggang lima. I-confirm ang rates sa ranger station.',
   'tourism.benguet.gov.ph, lakbaypinas.com',
   '[{"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}]'::jsonb, '2026-09'),
  ('pulag-05-ambangeg-trail-en', 'pulag', 'getting_there', 'en',
   'The Ambangeg Trail is the easiest and most used way up Mt. Pulag; Pinoy Mountaineer rates it 3 out of 9. It starts at the ranger station in Bashoy, Kabayan, climbs through mossy forest to Camp 1 and Camp 2 (about 2,700 m), then crosses open grassland to the summit. OpenStreetMap puts it at about 7.4 km one way. Benguet Province says it takes 4 to 5 hours; a 2026 guide gives about 1 hour to Camp 1, 2 more to Camp 2, and 1 to 2 to the top.',
   'pinoymountaineer.com, openstreetmap.org, lakbaypinas.com, tourism.benguet.gov.ph',
   '[{"id": "P3", "title": "Mt. Pulag Ambangeg Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2007/09/mt-pulag-2922.html", "published": "2015-12-03", "accessed": "2026-10-10"}, {"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}]'::jsonb, '2026-09'),
  ('pulag-05-ambangeg-trail-fil', 'pulag', 'getting_there', 'fil',
   'Ang Ambangeg Trail ang pinakamadali at pinakaginagamit na daan paakyat ng Mt. Pulag; 3 sa 9 ito ayon sa Pinoy Mountaineer. Nagsisimula ito sa ranger station sa Bashoy, Kabayan, umaakyat sa mossy forest papuntang Camp 1 at Camp 2 (mga 2,700 m), tapos tumatawid sa open grassland hanggang summit. Mga 7.4 km ito one way ayon sa OpenStreetMap. Ayon sa Benguet Province, 4 hanggang 5 oras ito; ayon sa isang 2026 guide, mga 1 oras papuntang Camp 1, 2 pa papuntang Camp 2, at 1 hanggang 2 papuntang tuktok.',
   'pinoymountaineer.com, openstreetmap.org, lakbaypinas.com, tourism.benguet.gov.ph',
   '[{"id": "P3", "title": "Mt. Pulag Ambangeg Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2007/09/mt-pulag-2922.html", "published": "2015-12-03", "accessed": "2026-10-10"}, {"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}]'::jsonb, '2026-09'),
  ('pulag-06-ranger-station-name-en', 'pulag', 'getting_there', 'en',
   'The Ambangeg Trail starts at a ranger station in Bashoy, Kabayan, uphill from the DENR Visitor Center in Ambangeg, Bokod. Its name is spelled several ways. A 2016 DENR notice quoted by Rappler, and OpenStreetMap, say "Babadak Ranger Station". Pinoy Mountaineer writes "Badabak". Benguet Province (2026) calls the route the "Babalak Trail", the name OpenStreetMap gives the trailhead. They all mean the same jump-off, where guides are hired. If you''re unsure, ask for the Ambangeg ranger station in Bashoy.',
   'openstreetmap.org, rappler.com, pinoymountaineer.com, tourism.benguet.gov.ph',
   '[{"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P27", "title": "DENR imposes stricter rules for Mt Pulag trekkers", "publisher": "Rappler", "url": "https://www.rappler.com/philippines/122314-denr-imposes-stricter-rules-for-mt-pulag-trekkers/", "published": "2016-02-13", "accessed": "2026-10-10"}, {"id": "P3", "title": "Mt. Pulag Ambangeg Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2007/09/mt-pulag-2922.html", "published": "2015-12-03", "accessed": "2026-10-10"}, {"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}]'::jsonb, '2026-09'),
  ('pulag-06-ranger-station-name-fil', 'pulag', 'getting_there', 'fil',
   'Nagsisimula ang Ambangeg Trail sa ranger station sa Bashoy, Kabayan, paakyat mula sa DENR Visitor Center sa Ambangeg, Bokod. Iba-iba ang baybay ng pangalan nito. "Babadak Ranger Station" ang nakasulat sa isang 2016 DENR notice na binanggit ng Rappler, at sa OpenStreetMap. "Badabak" naman sa Pinoy Mountaineer. "Babalak Trail" ang tawag ng Benguet Province (2026), ang pangalang ibinigay ng OpenStreetMap sa trailhead. Iisang jump-off ang tinutukoy nila, kung saan kumukuha ng guide. Kung hindi sigurado, itanong ang Ambangeg ranger station sa Bashoy.',
   'openstreetmap.org, rappler.com, pinoymountaineer.com, tourism.benguet.gov.ph',
   '[{"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P27", "title": "DENR imposes stricter rules for Mt Pulag trekkers", "publisher": "Rappler", "url": "https://www.rappler.com/philippines/122314-denr-imposes-stricter-rules-for-mt-pulag-trekkers/", "published": "2016-02-13", "accessed": "2026-10-10"}, {"id": "P3", "title": "Mt. Pulag Ambangeg Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2007/09/mt-pulag-2922.html", "published": "2015-12-03", "accessed": "2026-10-10"}, {"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}]'::jsonb, '2026-09'),
  ('pulag-07-akiki-trail-en', 'pulag', 'getting_there', 'en',
   'The Akiki Trail, nicknamed the "Killer Trail", starts at Akiki in Barangay Duacan, Kabayan. Pinoy Mountaineer rates it 7 out of 9: steep pine slopes and 10 to 11 hours of hiking to the summit, usually over 2 to 4 days, with camps and water at Eddet River and Marlboro Country. It closed after tropical cyclone Uwan damaged the Atapuan Bridge in 2025 and reopened on 9 January 2026, the Philippine Information Agency reported; the repaired bridge holds at most three people at a time.',
   'pinoymountaineer.com, openstreetmap.org, tourism.benguet.gov.ph, pia.gov.ph',
   '[{"id": "P4", "title": "Mt. Pulag/Akiki Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2008/02/mt-pulagakiki-trail-2922.html", "published": "2015-10-12", "accessed": "2026-10-10"}, {"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}, {"id": "P31", "title": "Frost hits Mount Pulag; Akiki Trail opens Jan. 9", "publisher": "Philippine Information Agency", "url": "https://pia.gov.ph/news/frost-hits-mount-pulag-akiki-trail-opens-jan-9/", "published": "2026-01", "accessed": "2026-10-10"}]'::jsonb, '2026-01'),
  ('pulag-07-akiki-trail-fil', 'pulag', 'getting_there', 'fil',
   'Ang Akiki Trail, na tinatawag na "Killer Trail", ay nagsisimula sa Akiki, Barangay Duacan, Kabayan. 7 sa 9 ito ayon sa Pinoy Mountaineer: matarik na pine slopes at 10 hanggang 11 oras na lakaran papuntang summit, karaniwang 2 hanggang 4 na araw, may camp at tubig sa Eddet River at Marlboro Country. Isinara ito matapos masira ng bagyong Uwan ang Atapuan Bridge noong 2025, at binuksan ulit noong 9 Enero 2026 ayon sa Philippine Information Agency; hanggang tatlong tao lang nang sabay ang kaya ng inayos na tulay.',
   'pinoymountaineer.com, openstreetmap.org, tourism.benguet.gov.ph, pia.gov.ph',
   '[{"id": "P4", "title": "Mt. Pulag/Akiki Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2008/02/mt-pulagakiki-trail-2922.html", "published": "2015-10-12", "accessed": "2026-10-10"}, {"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}, {"id": "P31", "title": "Frost hits Mount Pulag; Akiki Trail opens Jan. 9", "publisher": "Philippine Information Agency", "url": "https://pia.gov.ph/news/frost-hits-mount-pulag-akiki-trail-opens-jan-9/", "published": "2026-01", "accessed": "2026-10-10"}]'::jsonb, '2026-01'),
  ('pulag-08-tawangan-trail-en', 'pulag', 'getting_there', 'en',
   'The Tawangan Trail starts at Sitio Labang, Barangay Tawangan, Kabayan. Pinoy Mountaineer rates it 6 out of 9, with 10 to 11 hours of hiking to the summit over about 3 days. Day 2 crosses a long mossy forest where leeches are common, and a stream in the grassland is the last water before the saddle camp. In 2015 DENR discouraged this route. Benguet Province (2026) lists guide rates for an Akiki–Tawangan route, but ask the park office whether it is open. For leech bites, open the Leech bites Guide.',
   'openstreetmap.org, pinoymountaineer.com, tourism.benguet.gov.ph',
   '[{"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P12", "title": "Mt. Pulag/Tawangan Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/?p=1307", "published": "2015-09-06", "accessed": "2026-10-10"}, {"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}]'::jsonb, '2026-09'),
  ('pulag-08-tawangan-trail-fil', 'pulag', 'getting_there', 'fil',
   'Ang Tawangan Trail ay nagsisimula sa Sitio Labang, Barangay Tawangan, Kabayan. 6 sa 9 ito ayon sa Pinoy Mountaineer, 10 hanggang 11 oras na lakaran sa mga 3 araw. Sa ikalawang araw, dadaan sa mahabang mossy forest na maraming limatik, at isang sapa sa grassland ang huling tubig bago ang saddle camp. Noong 2015, hindi ito hinihikayat ng DENR. May guide rates ang Benguet Province (2026) para sa Akiki–Tawangan, pero itanong sa park office kung bukas ito. Para sa kagat ng limatik, buksan ang Guide na Leech bites.',
   'openstreetmap.org, pinoymountaineer.com, tourism.benguet.gov.ph',
   '[{"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P12", "title": "Mt. Pulag/Tawangan Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/?p=1307", "published": "2015-09-06", "accessed": "2026-10-10"}, {"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}]'::jsonb, '2026-09'),
  ('pulag-09-ambaguio-trail-en', 'pulag', 'getting_there', 'en',
   'The Ambaguio Trail is the longest way up Mt. Pulag, from Nueva Vizcaya. In 2019 hikers registered at the Ambaguio Municipal Hall, reached by jeep from Bayombong. A 2019 trip report describes about 24 km with roughly 2,300 m of climbing, via Sitio Dagadag, Napo and a bunkhouse at Sitio Balete, up to the summit grassland. It usually takes 3 days. One travel site says it needs a special permit. Confirm the permit, guide and orientation with the park office first.',
   'openstreetmap.org, lakwatsero.com, joanathx.com',
   '[{"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P13", "title": "Tales from Mount Pulag: Ambaguio – Akiki Overnight Traverse", "publisher": "Lakwatsero", "url": "https://lakwatsero.com/trail-tale/mount-pulag-ambaguio-akiki-overnight-traverse", "published": "2019", "accessed": "2026-10-10"}, {"id": "P22", "title": "Mount Pulag Travel Guide 2026", "publisher": "joanathx", "url": "https://joanathx.com/mount-pulag-travel-guide/", "published": "2026", "accessed": "2026-10-10"}]'::jsonb, '2019'),
  ('pulag-09-ambaguio-trail-fil', 'pulag', 'getting_there', 'fil',
   'Ang Ambaguio Trail ang pinakamahabang daan paakyat ng Mt. Pulag, mula sa Nueva Vizcaya. Noong 2019, nagre-register ang mga hiker sa Ambaguio Municipal Hall, na mararating sakay ng jeep mula Bayombong. Ayon sa isang trip report noong 2019, mga 24 km ito na may mga 2,300 m na akyatin, dumadaan sa Sitio Dagadag, Napo at isang bunkhouse sa Sitio Balete, hanggang sa grassland ng summit. Karaniwang 3 araw ito. Ayon sa isang travel site, kailangan ng special permit. I-confirm muna sa park office ang permit, guide at orientation.',
   'openstreetmap.org, lakwatsero.com, joanathx.com',
   '[{"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P13", "title": "Tales from Mount Pulag: Ambaguio – Akiki Overnight Traverse", "publisher": "Lakwatsero", "url": "https://lakwatsero.com/trail-tale/mount-pulag-ambaguio-akiki-overnight-traverse", "published": "2019", "accessed": "2026-10-10"}, {"id": "P22", "title": "Mount Pulag Travel Guide 2026", "publisher": "joanathx", "url": "https://joanathx.com/mount-pulag-travel-guide/", "published": "2026", "accessed": "2026-10-10"}]'::jsonb, '2019'),
  ('pulag-10-campsites-and-camping-rules-en', 'pulag', 'campsites', 'en',
   'On the Ambangeg Trail, the campsites are Camp 1 in the mossy forest and Camp 2 at the edge of the grassland. Camping on the summit and open fires aren''t allowed. In February 2025 the park office closed Camps 1 and 2 for clean-up, and no official reopening notice was found. A November 2025 trip report camped at Camp 2, and a 2026 guide says camping is allowed on weekdays only, as a 2016 DENR notice also said. Ask the park office which camps are open.',
   'tribune.net.ph, rappler.com, ditokayshellan.com, lakbaypinas.com, pinoymountaineer.com',
   '[{"id": "P7", "title": "Garbage overwhelms Mt. Pulag", "publisher": "Daily Tribune", "url": "https://tribune.net.ph/2025/02/20/garbage-overwhelms-mt-pulag", "published": "2025-02-20", "accessed": "2026-10-10"}, {"id": "P27", "title": "DENR imposes stricter rules for Mt Pulag trekkers", "publisher": "Rappler", "url": "https://www.rappler.com/philippines/122314-denr-imposes-stricter-rules-for-mt-pulag-trekkers/", "published": "2016-02-13", "accessed": "2026-10-10"}, {"id": "P28", "title": "Mt. Pulag Overnight Itinerary: Mighty and Spectacular Sea of Clouds (trip report, climbed about November 2025)", "publisher": "Dito Kay Shellan", "url": "https://ditokayshellan.com/2025/11/11/mt-pulag-overnight-itinerary-mighty-and-spectacular-sea-of-clouds/", "published": "2025-11-11", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P3", "title": "Mt. Pulag Ambangeg Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2007/09/mt-pulag-2922.html", "published": "2015-12-03", "accessed": "2026-10-10"}]'::jsonb, '2026-02'),
  ('pulag-10-campsites-and-camping-rules-fil', 'pulag', 'campsites', 'fil',
   'Sa Ambangeg Trail, ang mga campsite ay Camp 1 sa mossy forest at Camp 2 sa gilid ng grassland. Bawal mag-camp sa summit at bawal ang open fire. Noong Pebrero 2025, isinara ng park office ang Camp 1 at Camp 2 para linisin, at walang nakitang opisyal na abiso na bukas na ulit. Nag-camp sa Camp 2 ang isang grupo noong Nobyembre 2025, at ayon sa isang 2026 guide, weekdays lang puwedeng mag-camp, gaya ng sabi ng DENR noong 2016. Itanong sa park office kung aling camp ang bukas.',
   'tribune.net.ph, rappler.com, ditokayshellan.com, lakbaypinas.com, pinoymountaineer.com',
   '[{"id": "P7", "title": "Garbage overwhelms Mt. Pulag", "publisher": "Daily Tribune", "url": "https://tribune.net.ph/2025/02/20/garbage-overwhelms-mt-pulag", "published": "2025-02-20", "accessed": "2026-10-10"}, {"id": "P27", "title": "DENR imposes stricter rules for Mt Pulag trekkers", "publisher": "Rappler", "url": "https://www.rappler.com/philippines/122314-denr-imposes-stricter-rules-for-mt-pulag-trekkers/", "published": "2016-02-13", "accessed": "2026-10-10"}, {"id": "P28", "title": "Mt. Pulag Overnight Itinerary: Mighty and Spectacular Sea of Clouds (trip report, climbed about November 2025)", "publisher": "Dito Kay Shellan", "url": "https://ditokayshellan.com/2025/11/11/mt-pulag-overnight-itinerary-mighty-and-spectacular-sea-of-clouds/", "published": "2025-11-11", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P3", "title": "Mt. Pulag Ambangeg Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2007/09/mt-pulag-2922.html", "published": "2015-12-03", "accessed": "2026-10-10"}]'::jsonb, '2026-02'),
  ('pulag-11-water-on-the-trails-en', 'pulag', 'water', 'en',
   'On the Ambangeg Trail, OpenStreetMap shows a spring between Camp 1 and Camp 2 and another beside Camp 2, and Pinoy Mountaineer puts a source about 100 m from Camp 2. There''s no water above Camp 2 or at the summit. A 2026 guide says to carry at least 2 litres from the ranger station. No official source says how reliable they are. Treat all water before drinking: open the Purifying water Guide. If someone shows signs of dehydration, open the Dehydration Guide.',
   'pinoymountaineer.com, openstreetmap.org, lakbaypinas.com',
   '[{"id": "P3", "title": "Mt. Pulag Ambangeg Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2007/09/mt-pulag-2922.html", "published": "2015-12-03", "accessed": "2026-10-10"}, {"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}]'::jsonb, '2026-02'),
  ('pulag-11-water-on-the-trails-fil', 'pulag', 'water', 'fil',
   'Ayon sa OpenStreetMap, may bukal sa Ambangeg Trail sa pagitan ng Camp 1 at Camp 2 at sa tabi ng Camp 2; ayon sa Pinoy Mountaineer, may source mga 100 m mula Camp 2. Walang tubig lampas sa Camp 2. Magdala ng 2 litro o higit pa mula ranger station, payo ng isang 2026 guide. Walang opisyal na ulat kung maaasahan ang mga ito. Linisin muna ang lahat ng tubig bago inumin: buksan ang Guide na Purifying water. Kung may senyales ng dehydration, buksan ang Guide na Dehydration.',
   'pinoymountaineer.com, openstreetmap.org, lakbaypinas.com',
   '[{"id": "P3", "title": "Mt. Pulag Ambangeg Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2007/09/mt-pulag-2922.html", "published": "2015-12-03", "accessed": "2026-10-10"}, {"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}]'::jsonb, '2026-02'),
  ('pulag-12-cold-frost-and-wind-en', 'pulag', 'hazards', 'en',
   'Mt. Pulag is cold all year and coldest from December to February. PAGASA had no station there in 2013, so summit temperatures are reports, such as −2 °C in December 2015 (Philstar). Frost forms on the grassland in cold spells; in January 2026 Kabayan''s mayor warned hikers not to underestimate the cold and to dress in layers. The park office has warned that waiting over an hour on the summit without proper clothing can cause hypothermia. If someone is shivering hard or confused, open the Hypothermia Emergency Guide.',
   'en.wikipedia.org, pinoymountaineer.com, philstar.com, pia.gov.ph, gurupress-cordillera.com',
   '[{"id": "P2", "title": "Mount Pulag", "publisher": "Wikipedia contributors", "url": "https://en.wikipedia.org/wiki/Mount_Pulag", "published": "2026-08-15", "accessed": "2026-10-10"}, {"id": "P3", "title": "Mt. Pulag Ambangeg Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2007/09/mt-pulag-2922.html", "published": "2015-12-03", "accessed": "2026-10-10"}, {"id": "P29", "title": "Mt. Pulag freezes below zero", "publisher": "The Philippine Star", "url": "https://www.philstar.com/headlines/2015/12/29/1537575/mt-pulag-freezes-below-zero", "published": "2015-12-29", "accessed": "2026-10-10"}, {"id": "P30", "title": "Viewpoint: Mt. Pulag may be the coldest place in the Philippines, but we need a thermometer to say exactly how cold", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2013/02/viewpoint-mt-pulag-may-be-coldest-place.html", "published": "2013-02-01", "accessed": "2026-10-10"}, {"id": "P31", "title": "Frost hits Mount Pulag; Akiki Trail opens Jan. 9", "publisher": "Philippine Information Agency", "url": "https://pia.gov.ph/news/frost-hits-mount-pulag-akiki-trail-opens-jan-9/", "published": "2026-01", "accessed": "2026-10-10"}, {"id": "P14", "title": "Mt. Pulag re-opens for tourist, midnight trekking prohibited", "publisher": "Gurupress Cordillera", "url": "https://www.gurupress-cordillera.com/post/mt-pulag-re-opens-for-tourist-midnight-trekking-prohibited", "published": "2022-06-12", "accessed": "2026-10-10"}]'::jsonb, '2026-01'),
  ('pulag-12-cold-frost-and-wind-fil', 'pulag', 'hazards', 'fil',
   'Malamig sa Mt. Pulag buong taon, lalo na mula Disyembre hanggang Pebrero. Walang station ang PAGASA rito noong 2013, kaya ulat lang ang mga temperatura sa summit, gaya ng −2 °C noong Disyembre 2015 (Philstar). Nagkaka-frost sa grassland; noong Enero 2026, nagbabala ang mayor ng Kabayan na huwag maliitin ang lamig at mag-layer ng damit. Ayon sa park office, ang paghihintay nang mahigit isang oras sa summit nang kulang ang damit ay puwedeng magdulot ng hypothermia. Kung may nanginginig nang husto o nalilito, buksan ang Emergency Guide na Hypothermia.',
   'en.wikipedia.org, pinoymountaineer.com, philstar.com, pia.gov.ph, gurupress-cordillera.com',
   '[{"id": "P2", "title": "Mount Pulag", "publisher": "Wikipedia contributors", "url": "https://en.wikipedia.org/wiki/Mount_Pulag", "published": "2026-08-15", "accessed": "2026-10-10"}, {"id": "P3", "title": "Mt. Pulag Ambangeg Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2007/09/mt-pulag-2922.html", "published": "2015-12-03", "accessed": "2026-10-10"}, {"id": "P29", "title": "Mt. Pulag freezes below zero", "publisher": "The Philippine Star", "url": "https://www.philstar.com/headlines/2015/12/29/1537575/mt-pulag-freezes-below-zero", "published": "2015-12-29", "accessed": "2026-10-10"}, {"id": "P30", "title": "Viewpoint: Mt. Pulag may be the coldest place in the Philippines, but we need a thermometer to say exactly how cold", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2013/02/viewpoint-mt-pulag-may-be-coldest-place.html", "published": "2013-02-01", "accessed": "2026-10-10"}, {"id": "P31", "title": "Frost hits Mount Pulag; Akiki Trail opens Jan. 9", "publisher": "Philippine Information Agency", "url": "https://pia.gov.ph/news/frost-hits-mount-pulag-akiki-trail-opens-jan-9/", "published": "2026-01", "accessed": "2026-10-10"}, {"id": "P14", "title": "Mt. Pulag re-opens for tourist, midnight trekking prohibited", "publisher": "Gurupress Cordillera", "url": "https://www.gurupress-cordillera.com/post/mt-pulag-re-opens-for-tourist-midnight-trekking-prohibited", "published": "2022-06-12", "accessed": "2026-10-10"}]'::jsonb, '2026-01'),
  ('pulag-13-altitude-en', 'pulag', 'hazards', 'en',
   'Mt. Pulag is the one Tahak Destination high enough for altitude to matter. The summit is about 2,922 m and Camp 2 about 2,700 m. The US CDC says people who sleep at about 2,450 m or higher before getting used to the altitude risk altitude illness, so campers at Camp 2 can be affected. Headache with nausea, dizziness, tiredness or poor appetite can be early signs. If you or a companion feel unwell up high, open the Altitude sickness Emergency Guide.',
   'openstreetmap.org, car.denr.gov.ph, cdc.gov',
   '[{"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P15", "title": "Moreno personally leads ground assessment in Mt. Pulag", "publisher": "DENR-CAR", "url": "https://car.denr.gov.ph/news-events/moreno-personally-leads-ground-assessment-in-mt-pulag/", "published": "2025", "accessed": "2026-10-10"}, {"id": "S9", "title": "High-Altitude Travel and Altitude Illness (CDC Yellow Book 2026)", "publisher": "US Centers for Disease Control and Prevention", "url": "https://www.cdc.gov/yellow-book/hcp/environmental-hazards-risks/high-altitude-travel-and-altitude-illness.html", "published": "2025-04-23", "accessed": "2026-10-10"}]'::jsonb, '2025-05'),
  ('pulag-13-altitude-fil', 'pulag', 'hazards', 'fil',
   'Ang Mt. Pulag lang ang Destination sa Tahak na sapat ang taas para maging isyu ang altitude. Mga 2,922 m ang summit at mga 2,700 m ang Camp 2. Ayon sa US CDC, puwedeng magka-altitude illness ang natutulog sa mga 2,450 m o mas mataas bago masanay sa taas, kaya puwedeng tamaan ang mga nagka-camp sa Camp 2. Ang sakit ng ulo na may pagduduwal, pagkahilo, pagod o walang ganang kumain ay puwedeng maagang senyales. Kung masama ang pakiramdam ninyo sa taas, buksan ang Emergency Guide na Altitude sickness.',
   'openstreetmap.org, car.denr.gov.ph, cdc.gov',
   '[{"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P15", "title": "Moreno personally leads ground assessment in Mt. Pulag", "publisher": "DENR-CAR", "url": "https://car.denr.gov.ph/news-events/moreno-personally-leads-ground-assessment-in-mt-pulag/", "published": "2025", "accessed": "2026-10-10"}, {"id": "S9", "title": "High-Altitude Travel and Altitude Illness (CDC Yellow Book 2026)", "publisher": "US Centers for Disease Control and Prevention", "url": "https://www.cdc.gov/yellow-book/hcp/environmental-hazards-risks/high-altitude-travel-and-altitude-illness.html", "published": "2025-04-23", "accessed": "2026-10-10"}]'::jsonb, '2025-05'),
  ('pulag-14-summit-sunrise-timing-en', 'pulag', 'hazards', 'en',
   'Most Ambangeg hikers aim to reach the summit at sunrise. A group camping at Camp 2 in November 2025 left at 4:30 AM and reached the top at 6:00 AM. A 2026 guide describes leaving the ranger station around 2:00 AM instead. In 2022 the park office advised against midnight trekking and asked hikers to keep to allowed trekking times, so follow your guide and the orientation. The summit is cold and windy; if someone gets very cold, open the Hypothermia Emergency Guide.',
   'gurupress-cordillera.com, lakbaypinas.com, ditokayshellan.com',
   '[{"id": "P14", "title": "Mt. Pulag re-opens for tourist, midnight trekking prohibited", "publisher": "Gurupress Cordillera", "url": "https://www.gurupress-cordillera.com/post/mt-pulag-re-opens-for-tourist-midnight-trekking-prohibited", "published": "2022-06-12", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P28", "title": "Mt. Pulag Overnight Itinerary: Mighty and Spectacular Sea of Clouds (trip report, climbed about November 2025)", "publisher": "Dito Kay Shellan", "url": "https://ditokayshellan.com/2025/11/11/mt-pulag-overnight-itinerary-mighty-and-spectacular-sea-of-clouds/", "published": "2025-11-11", "accessed": "2026-10-10"}]'::jsonb, '2026-02'),
  ('pulag-14-summit-sunrise-timing-fil', 'pulag', 'hazards', 'fil',
   'Karamihan ng hiker sa Ambangeg ay gustong umabot sa summit pagsikat ng araw. Isang grupong nag-camp sa Camp 2 noong Nobyembre 2025 ang umalis nang 4:30 AM at nakarating sa tuktok nang 6:00 AM. Ayon naman sa isang 2026 guide, umaalis sila sa ranger station bandang 2:00 AM. Noong 2022, pinayuhan ng park office na iwasan ang midnight trekking at sundin ang pinapayagang oras, kaya sundin ang guide at ang orientation. Malamig at mahangin sa summit; kung may sobrang nilalamig, buksan ang Emergency Guide na Hypothermia.',
   'gurupress-cordillera.com, lakbaypinas.com, ditokayshellan.com',
   '[{"id": "P14", "title": "Mt. Pulag re-opens for tourist, midnight trekking prohibited", "publisher": "Gurupress Cordillera", "url": "https://www.gurupress-cordillera.com/post/mt-pulag-re-opens-for-tourist-midnight-trekking-prohibited", "published": "2022-06-12", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P28", "title": "Mt. Pulag Overnight Itinerary: Mighty and Spectacular Sea of Clouds (trip report, climbed about November 2025)", "publisher": "Dito Kay Shellan", "url": "https://ditokayshellan.com/2025/11/11/mt-pulag-overnight-itinerary-mighty-and-spectacular-sea-of-clouds/", "published": "2025-11-11", "accessed": "2026-10-10"}]'::jsonb, '2026-02'),
  ('pulag-15-weather-fire-and-closures-en', 'pulag', 'hazards', 'en',
   'PAGASA''s rainy season runs from June to November. The park board and park office, not the towns, decide closures, and hikes have been suspended in stormy weather even for paid bookings. Check PAGASA''s tropical cyclone wind signals before you travel. After tropical cyclone Uwan in 2025, the Akiki Trail stayed closed until January 2026. Grass fires closed the mountain in 2018, 2019 and 2020. The summit grassland has no shelter from thunderstorms; if you hear thunder, open the Lightning Emergency Guide.',
   'pagasa.dost.gov.ph, sunstar.com.ph, en.wikipedia.org, pia.gov.ph',
   '[{"id": "P32", "title": "Climate of the Philippines", "publisher": "PAGASA (DOST)", "url": "https://www.pagasa.dost.gov.ph/information/climate-philippines", "published": "undated", "accessed": "2026-10-10"}, {"id": "S12", "title": "Tropical Cyclone Wind Signal", "publisher": "PAGASA (DOST)", "url": "https://www.pagasa.dost.gov.ph/learning-tools/tropical-cyclone-wind-signal", "published": "undated", "accessed": "2026-10-10"}, {"id": "P8", "title": "Environment office cautions Pulag hikers", "publisher": "SunStar", "url": "https://www.sunstar.com.ph/more-articles/environment-office-cautions-pulag-hikers", "published": "2010-07-29", "accessed": "2026-10-10"}, {"id": "P2", "title": "Mount Pulag", "publisher": "Wikipedia contributors", "url": "https://en.wikipedia.org/wiki/Mount_Pulag", "published": "2026-08-15", "accessed": "2026-10-10"}, {"id": "P31", "title": "Frost hits Mount Pulag; Akiki Trail opens Jan. 9", "publisher": "Philippine Information Agency", "url": "https://pia.gov.ph/news/frost-hits-mount-pulag-akiki-trail-opens-jan-9/", "published": "2026-01", "accessed": "2026-10-10"}]'::jsonb, '2026-01'),
  ('pulag-15-weather-fire-and-closures-fil', 'pulag', 'hazards', 'fil',
   'Hunyo hanggang Nobyembre ang tag-ulan ayon sa PAGASA. Ang park board at park office, hindi ang mga bayan, ang nagpapasya kung isasara ang bundok, at sinususpinde ang hike kapag may bagyo, kahit bayad na ang booking. Tingnan ang tropical cyclone wind signals ng PAGASA bago bumiyahe. Pagkatapos ng bagyong Uwan noong 2025, sarado ang Akiki Trail hanggang Enero 2026. Isinara ang bundok dahil sa sunog sa damuhan noong 2018, 2019 at 2020. Walang masisilungan sa grassland ng summit kapag may kulog; buksan ang Emergency Guide na Lightning.',
   'pagasa.dost.gov.ph, sunstar.com.ph, en.wikipedia.org, pia.gov.ph',
   '[{"id": "P32", "title": "Climate of the Philippines", "publisher": "PAGASA (DOST)", "url": "https://www.pagasa.dost.gov.ph/information/climate-philippines", "published": "undated", "accessed": "2026-10-10"}, {"id": "S12", "title": "Tropical Cyclone Wind Signal", "publisher": "PAGASA (DOST)", "url": "https://www.pagasa.dost.gov.ph/learning-tools/tropical-cyclone-wind-signal", "published": "undated", "accessed": "2026-10-10"}, {"id": "P8", "title": "Environment office cautions Pulag hikers", "publisher": "SunStar", "url": "https://www.sunstar.com.ph/more-articles/environment-office-cautions-pulag-hikers", "published": "2010-07-29", "accessed": "2026-10-10"}, {"id": "P2", "title": "Mount Pulag", "publisher": "Wikipedia contributors", "url": "https://en.wikipedia.org/wiki/Mount_Pulag", "published": "2026-08-15", "accessed": "2026-10-10"}, {"id": "P31", "title": "Frost hits Mount Pulag; Akiki Trail opens Jan. 9", "publisher": "Philippine Information Agency", "url": "https://pia.gov.ph/news/frost-hits-mount-pulag-akiki-trail-opens-jan-9/", "published": "2026-01", "accessed": "2026-10-10"}]'::jsonb, '2026-01'),
  ('pulag-16-emergency-contacts-and-hospitals-en', 'pulag', 'hazards', 'en',
   'For any emergency on Mt. Pulag, call 911, the national emergency hotline, if you have signal; Pinoy Mountaineer says signal is weak at Camp 2 and better at the summit. Tell your guide and the rangers at once. No official number for the Kabayan or Bokod disaster office was found. The nearest hospital to the ranger station is Dennis Molintas District Hospital in Bokod, about 9 km away in a straight line and further by road. Benguet General Hospital in La Trinidad is about 34 km away.',
   'pinoymountaineer.com, openstreetmap.org, philhealth.gov.ph, lawphil.net',
   '[{"id": "P3", "title": "Mt. Pulag Ambangeg Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2007/09/mt-pulag-2922.html", "published": "2015-12-03", "accessed": "2026-10-10"}, {"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P25", "title": "PhilHealth accredited hospitals list (2025)", "publisher": "PhilHealth", "url": "https://www.philhealth.gov.ph/partners/providers/facilities/accredited/HOSP_053125.pdf", "published": "2025", "accessed": "2026-10-10"}, {"id": "S23", "title": "Executive Order No. 56, s. 2018 (Emergency 911)", "publisher": "Republic of the Philippines (text via LawPhil)", "url": "https://lawphil.net/executive/execord/eo2018/eo_56_2018.html", "published": "2018-05-25", "accessed": "2026-10-10"}]'::jsonb, '2026-10'),
  ('pulag-16-emergency-contacts-and-hospitals-fil', 'pulag', 'hazards', 'fil',
   'Sa anumang emergency sa Mt. Pulag, tumawag sa 911, ang pambansang emergency hotline, kung may signal; ayon sa Pinoy Mountaineer, mahina ang signal sa Camp 2 at mas maayos sa summit. Sabihan agad ang guide at ang mga ranger. Walang nakitang opisyal na numero ng disaster office ng Kabayan o Bokod. Ang pinakamalapit na ospital sa ranger station ay ang Dennis Molintas District Hospital sa Bokod, mga 9 km nang tuwiran at mas malayo sa kalsada. Mga 34 km naman ang Benguet General Hospital sa La Trinidad.',
   'pinoymountaineer.com, openstreetmap.org, philhealth.gov.ph, lawphil.net',
   '[{"id": "P3", "title": "Mt. Pulag Ambangeg Trail (2,922+)", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2007/09/mt-pulag-2922.html", "published": "2015-12-03", "accessed": "2026-10-10"}, {"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}, {"id": "P25", "title": "PhilHealth accredited hospitals list (2025)", "publisher": "PhilHealth", "url": "https://www.philhealth.gov.ph/partners/providers/facilities/accredited/HOSP_053125.pdf", "published": "2025", "accessed": "2026-10-10"}, {"id": "S23", "title": "Executive Order No. 56, s. 2018 (Emergency 911)", "publisher": "Republic of the Philippines (text via LawPhil)", "url": "https://lawphil.net/executive/execord/eo2018/eo_56_2018.html", "published": "2018-05-25", "accessed": "2026-10-10"}]'::jsonb, '2026-10'),
  ('pulag-17-leave-no-trace-and-park-rules-en', 'pulag', 'registration', 'en',
   'Mt. Pulag is a protected area, so the Expanded NIPAS Act (RA 11038) applies: littering, dumping waste, taking or disturbing plants and animals, damaging trails, and causing fires are prohibited, with heavy penalties. Litter is the park''s biggest problem. Camps 1 and 2 were closed in 2025 for clean-up, and DENR-CAR led a clean-up hike on the Ambangeg Trail that June. Carry out every piece of trash, use the camp toilets, stay on the Trail, and respect the mountain as a sacred place.',
   'lawphil.net, tribune.net.ph, car.denr.gov.ph',
   '[{"id": "P1", "title": "Republic Act No. 11685, Mt. Pulag Protected Landscape Act (2022)", "publisher": "Republic of the Philippines (text via LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2022/ra_11685_2022.html", "published": "2022-04-08", "accessed": "2026-10-10"}, {"id": "P7", "title": "Garbage overwhelms Mt. Pulag", "publisher": "Daily Tribune", "url": "https://tribune.net.ph/2025/02/20/garbage-overwhelms-mt-pulag", "published": "2025-02-20", "accessed": "2026-10-10"}, {"id": "P16", "title": "DENR-CAR marks 38th anniversary with cleanup drive at Mt. Pulag", "publisher": "DENR-CAR", "url": "https://car.denr.gov.ph/news-events/denr-car-marks-38th-anniversary-with-cleanup-drive-at-mt-pulag/", "published": "2025-07", "accessed": "2026-10-10"}, {"id": "S22", "title": "Republic Act No. 11038, Expanded NIPAS Act (2018)", "publisher": "Republic of the Philippines (text via LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2018/ra_11038_2018.html", "published": "2018-06-22", "accessed": "2026-10-10"}]'::jsonb, '2025-07'),
  ('pulag-17-leave-no-trace-and-park-rules-fil', 'pulag', 'registration', 'fil',
   'Protected area ang Mt. Pulag, kaya umiiral ang Expanded NIPAS Act (RA 11038): bawal magkalat, magtapon ng basura, kumuha o gambalain ang mga halaman at hayop, sirain ang trail, at magdulot ng sunog, at mabigat ang parusa. Basura ang pinakamalaking problema ng park. Isinara ang Camp 1 at Camp 2 noong 2025 para linisin, at nanguna ang DENR-CAR sa isang clean-up hike sa Ambangeg Trail noong Hunyo. Iuwi ang lahat ng basura, gamitin ang toilet sa mga camp, manatili sa Trail, at igalang ang bundok bilang sagradong lugar.',
   'lawphil.net, tribune.net.ph, car.denr.gov.ph',
   '[{"id": "P1", "title": "Republic Act No. 11685, Mt. Pulag Protected Landscape Act (2022)", "publisher": "Republic of the Philippines (text via LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2022/ra_11685_2022.html", "published": "2022-04-08", "accessed": "2026-10-10"}, {"id": "P7", "title": "Garbage overwhelms Mt. Pulag", "publisher": "Daily Tribune", "url": "https://tribune.net.ph/2025/02/20/garbage-overwhelms-mt-pulag", "published": "2025-02-20", "accessed": "2026-10-10"}, {"id": "P16", "title": "DENR-CAR marks 38th anniversary with cleanup drive at Mt. Pulag", "publisher": "DENR-CAR", "url": "https://car.denr.gov.ph/news-events/denr-car-marks-38th-anniversary-with-cleanup-drive-at-mt-pulag/", "published": "2025-07", "accessed": "2026-10-10"}, {"id": "S22", "title": "Republic Act No. 11038, Expanded NIPAS Act (2018)", "publisher": "Republic of the Philippines (text via LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2018/ra_11038_2018.html", "published": "2018-06-22", "accessed": "2026-10-10"}]'::jsonb, '2025-07'),
  ('pulag-18-denr-orientation-en', 'pulag', 'registration', 'en',
   'Every Mt. Pulag hiker must register and attend a mandatory orientation at the DENR Visitor Center in Ambangeg, Bokod, before going to the ranger station (Benguet Province, 2026). This applies on every Trail. In 2016 the park began marking the hands of trekkers who had booked and attended, and turned back anyone without the mark (Rappler). A November 2025 group registered there at about 7:00 AM. A 2026 guide says the nearby clinic can have 2-hour queues on weekends, so arrive early.',
   'tourism.benguet.gov.ph, rappler.com, lakbaypinas.com, ditokayshellan.com',
   '[{"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}, {"id": "P27", "title": "DENR imposes stricter rules for Mt Pulag trekkers", "publisher": "Rappler", "url": "https://www.rappler.com/philippines/122314-denr-imposes-stricter-rules-for-mt-pulag-trekkers/", "published": "2016-02-13", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P28", "title": "Mt. Pulag Overnight Itinerary: Mighty and Spectacular Sea of Clouds (trip report, climbed about November 2025)", "publisher": "Dito Kay Shellan", "url": "https://ditokayshellan.com/2025/11/11/mt-pulag-overnight-itinerary-mighty-and-spectacular-sea-of-clouds/", "published": "2025-11-11", "accessed": "2026-10-10"}]'::jsonb, '2026-09'),
  ('pulag-18-denr-orientation-fil', 'pulag', 'registration', 'fil',
   'Lahat ng hiker sa Mt. Pulag ay kailangang mag-register at dumalo sa mandatory orientation sa DENR Visitor Center sa Ambangeg, Bokod, bago pumunta sa ranger station (Benguet Province, 2026). Para ito sa lahat ng Trail. Noong 2016, sinimulan ng park na markahan ang kamay ng mga naka-book at dumalo, at pinabalik ang walang marka (Rappler). Isang grupo noong Nobyembre 2025 ang nag-register doon bandang 7:00 AM. Ayon sa isang 2026 guide, puwedeng umabot ng 2 oras ang pila sa kalapit na clinic tuwing weekend, kaya pumunta nang maaga.',
   'tourism.benguet.gov.ph, rappler.com, lakbaypinas.com, ditokayshellan.com',
   '[{"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}, {"id": "P27", "title": "DENR imposes stricter rules for Mt Pulag trekkers", "publisher": "Rappler", "url": "https://www.rappler.com/philippines/122314-denr-imposes-stricter-rules-for-mt-pulag-trekkers/", "published": "2016-02-13", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P28", "title": "Mt. Pulag Overnight Itinerary: Mighty and Spectacular Sea of Clouds (trip report, climbed about November 2025)", "publisher": "Dito Kay Shellan", "url": "https://ditokayshellan.com/2025/11/11/mt-pulag-overnight-itinerary-mighty-and-spectacular-sea-of-clouds/", "published": "2025-11-11", "accessed": "2026-10-10"}]'::jsonb, '2026-09'),
  ('pulag-19-visitor-cap-en', 'pulag', 'registration', 'en',
   'Mt. Pulag limits how many people can climb. In 2013 DENR said only 120 climbers were allowed at a time. In February 2016, Rappler reported a cap of 500 trekkers a day and at most 20 people per group. DENR-CAR mentioned a daily carrying capacity again in 2022 without giving a number. 2026 travel guides still report 500 a day, and one says groups are now limited to 10. No official current figure was found, so confirm the limits with the park office when you book.',
   'rappler.com, sunstar.com.ph, car.denr.gov.ph, lakbaypinas.com, joanathx.com',
   '[{"id": "P27", "title": "DENR imposes stricter rules for Mt Pulag trekkers", "publisher": "Rappler", "url": "https://www.rappler.com/philippines/122314-denr-imposes-stricter-rules-for-mt-pulag-trekkers/", "published": "2016-02-13", "accessed": "2026-10-10"}, {"id": "P6", "title": "Only 120 climbers allowed in Pulag at a time – DENR", "publisher": "SunStar", "url": "https://www.sunstar.com.ph/more-articles/only-120-climbers-allowed-in-pulag-at-a-time-denr", "published": "2013-11-22", "accessed": "2026-10-10"}, {"id": "P19", "title": "Mt. Pulag to be opened for the Altitude OCR World Series Asia", "publisher": "DENR-CAR", "url": "https://car.denr.gov.ph/news-events/mt-pulag-to-be-opened-for-the-altitude-ocr-world-series-asia/", "published": "2022", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P22", "title": "Mount Pulag Travel Guide 2026", "publisher": "joanathx", "url": "https://joanathx.com/mount-pulag-travel-guide/", "published": "2026", "accessed": "2026-10-10"}]'::jsonb, '2026-06'),
  ('pulag-19-visitor-cap-fil', 'pulag', 'registration', 'fil',
   'May limitasyon kung ilan ang puwedeng umakyat sa Mt. Pulag. Noong 2013, sinabi ng DENR na 120 climber lang ang puwede nang sabay-sabay. Noong Pebrero 2016, iniulat ng Rappler na 500 trekker bawat araw ang cap at hanggang 20 tao bawat grupo. Binanggit ulit ng DENR-CAR ang daily carrying capacity noong 2022 pero walang bilang. Ayon sa mga 2026 travel guide, 500 pa rin bawat araw, at sabi ng isa, hanggang 10 na lang bawat grupo. Walang nakitang opisyal na bilang ngayon, kaya i-confirm sa park office kapag nag-book.',
   'rappler.com, sunstar.com.ph, car.denr.gov.ph, lakbaypinas.com, joanathx.com',
   '[{"id": "P27", "title": "DENR imposes stricter rules for Mt Pulag trekkers", "publisher": "Rappler", "url": "https://www.rappler.com/philippines/122314-denr-imposes-stricter-rules-for-mt-pulag-trekkers/", "published": "2016-02-13", "accessed": "2026-10-10"}, {"id": "P6", "title": "Only 120 climbers allowed in Pulag at a time – DENR", "publisher": "SunStar", "url": "https://www.sunstar.com.ph/more-articles/only-120-climbers-allowed-in-pulag-at-a-time-denr", "published": "2013-11-22", "accessed": "2026-10-10"}, {"id": "P19", "title": "Mt. Pulag to be opened for the Altitude OCR World Series Asia", "publisher": "DENR-CAR", "url": "https://car.denr.gov.ph/news-events/mt-pulag-to-be-opened-for-the-altitude-ocr-world-series-asia/", "published": "2022", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P22", "title": "Mount Pulag Travel Guide 2026", "publisher": "joanathx", "url": "https://joanathx.com/mount-pulag-travel-guide/", "published": "2026", "accessed": "2026-10-10"}]'::jsonb, '2026-06'),
  ('pulag-20-getting-to-the-jump-off-en', 'pulag', 'getting_there', 'en',
   'From Baguio or La Trinidad, ride a jeepney, van or bus bound for Kabayan or Bokod. Benguet Province says the trip takes about 4 to 5 hours; a 2026 guide says 2 to 3 hours, with vans to Kabayan leaving Baguio''s Old Slaughterhouse terminal from 7:00 AM. Stop first at the DENR Visitor Center in Ambangeg, Bokod, to register. Then ride up to the ranger station in Bashoy, Kabayan, about 25 to 30 minutes by habal-habal, the same guide says. Many hikers join tours that include transport.',
   'tourism.benguet.gov.ph, lakbaypinas.com, openstreetmap.org',
   '[{"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-09'),
  ('pulag-20-getting-to-the-jump-off-fil', 'pulag', 'getting_there', 'fil',
   'Mula Baguio o La Trinidad, sumakay ng jeep, van o bus papuntang Kabayan o Bokod. Ayon sa Benguet Province, mga 4 hanggang 5 oras ang biyahe; ayon sa isang 2026 guide, 2 hanggang 3 oras, at may van papuntang Kabayan sa Old Slaughterhouse terminal sa Baguio mula 7:00 AM. Dumaan muna sa DENR Visitor Center sa Ambangeg, Bokod, para mag-register. Tapos sumakay paakyat sa ranger station sa Bashoy, Kabayan, mga 25 hanggang 30 minuto sakay ng habal-habal, ayon sa parehong guide. Marami ang sumasali sa tour na may kasamang transportasyon.',
   'tourism.benguet.gov.ph, lakbaypinas.com, openstreetmap.org',
   '[{"id": "P26", "title": "Mt. Pulag (hiking rates, guides and how to get there)", "publisher": "Benguet Provincial Tourism Office", "url": "https://tourism.benguet.gov.ph/tourist_spots/mt-pulag/", "published": "2026-09-15", "accessed": "2026-10-10"}, {"id": "P21", "title": "Mt. Pulag Via Ambangeg Trail: Complete 2026 Hiking Guide (author climbed February 2026)", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/mt-pulag-travel-guide-ambangeg-trail/", "published": "2026-06-06", "accessed": "2026-10-10"}, {"id": "P11", "title": "OpenStreetMap data (Ambangeg route relation 3625651, camps, springs, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/relation/3625651", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-09');

commit;
